cd /workspace && cat > /tmp/filter_pc.py <<'EOF'
import subprocess, sys, re

mixed = [l.split(' ',1)[1].strip() for l in open('/tmp/hdfs_classify.txt') if l.startswith('MIXED')]
out_patches = []
mixed_hunks = []
for f in mixed:
    diff = subprocess.run(['git','diff','-U3','--',f], capture_output=True, text=True).stdout
    lines = diff.split('\n')
    header = []
    hunks = []
    cur = None
    for ln in lines:
        if ln.startswith('diff --git') or ln.startswith('index ') or ln.startswith('---') or ln.startswith('+++'):
            if cur is None:
                header.append(ln)
            else:
                # shouldn't happen inside hunks
                pass
        elif ln.startswith('@@'):
            if cur is not None: hunks.append(cur)
            cur = [ln]
        elif cur is not None:
            cur.append(ln)
    if cur is not None: hunks.append(cur)
    keep = []
    for h in hunks:
        changed = [l for l in h[1:] if l and l[0] in '+-' ]
        pc = [l for l in changed if 'precondition' in l.lower()]
        nonpc = [l for l in changed if 'precondition' not in l.lower()]
        if pc and not nonpc:
            keep.append(h)
        elif pc and nonpc:
            mixed_hunks.append((f, h))
    if keep:
        out_patches.append('\n'.join(header) + '\n' + '\n'.join('\n'.join(h).rstrip('\n') for h in keep) + '\n')

with open('/tmp/pc_mixed.patch','w') as fh:
    fh.write(''.join(out_patches))
print("mixed-hunk files needing manual review:", len(mixed_hunks))
for f,h in mixed_hunks:
    print("=== ", f)
    print('\n'.join(h))
EOF
python3 /tmp/filter_pc.py | head -100

